import { NextResponse } from 'next/server';

export async function POST(request: Request) {
  try {
    const { email, reportData } = await request.json();

    // In a real application, you would use 'nodemailer' or an API like SendGrid/Resend here.
    // For now, we simulate the email sending process.

    console.log(`[Email Service] Sending report to ${email || 'user@example.com'}`);
    console.log(`[Email Service] Subject: Your Financial Report`);
    console.log(`[Email Service] Body Summary: Income: ${reportData.income}, Expense: ${reportData.expense}`);

    // Simulate delay
    await new Promise(resolve => setTimeout(resolve, 1000));

    return NextResponse.json({ success: true, message: 'Report sent successfully' });
  } catch (error) {
    return NextResponse.json({ error: 'Failed to send email' }, { status: 500 });
  }
}
